        # двигателя и т.п.). Раньше это слово ВСЕГДА подставляло код
        # гигиенических прокладок, даже в чисто техническом контексте -
        # по требованию Яна теперь код подставляется только если рядом
        # в тексте карточки есть явное гигиеническое слово (см.
        # requires_context в resolver/candidate_scorer.py). Без такого
